//! Bakes the contributor credits into the binary as static Rust tables (`docs/contributors.md` →
//! Decision). Nothing is read at run time: `src/credits.rs` includes `OUT_DIR/credits.rs`.
//!
//! Adapted from PhotoCraft `crates/ui-egui/build.rs` (revision 184c226a); MIT OR Apache-2.0.
//!
//! - `contributors/contributors.json` (schema 1, generated by `cargo xtask contributors`): commit
//!   stats per GitHub username and the models of the `Co-Authored-By` trailers.
//! - `contributors/people.toml`: the names people chose for themselves. A name is used only when
//!   the JSON says the entry was verified (`people_entry`), as the refresh checks its owner.
//!
//! Only GitHub usernames, those chosen names, counts and dates are written: nothing that looks like
//! an email address ever reaches the binary (such a value is left out with a warning). A missing or
//! malformed file gives empty tables (or no names) and a warning, never a failed build: the strict
//! check of both files is `cargo xtask contributors --check`, run by `cargo xtask ci`.
//!
//! `crates/ui/tests/about.rs` includes this file to test [`generate`] on fixtures.

#![forbid(unsafe_code)]
#![deny(clippy::unwrap_used, clippy::expect_used, clippy::panic, clippy::unimplemented, clippy::todo, clippy::unreachable)]

use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::path::{Path, PathBuf};

use serde_json::Value;

fn main() {
    println!("cargo::rerun-if-changed=build.rs");
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("..").join("..").join("contributors");
    let json = read(&dir.join("contributors.json"), "the About window shows no contributors")
        .and_then(|t| {
            serde_json::from_str::<Value>(&t)
                .map_err(|e| warn(&dir.join("contributors.json"), &e.to_string(), "the About window shows no contributors"))
                .ok()
        })
        .unwrap_or(Value::Null);
    let people_path = dir.join("people.toml");
    let people = read(&people_path, "contributors are shown by username only").map(|t| parse_people(&t)).unwrap_or_default();
    for (line, problem) in &people.problems {
        println!("cargo::warning={}:{line}: {problem}; the line is ignored", people_path.display());
    }
    let (code, dropped) = generate(&json, &people.entries);
    for what in dropped {
        println!("cargo::warning=contributors: {what} looks like an email address and is left out of the binary");
    }
    let out = PathBuf::from(std::env::var_os("OUT_DIR").unwrap_or_default()).join("credits.rs");
    if let Err(e) = std::fs::write(&out, code) {
        println!("cargo::error=writing {}: {e}", out.display());
    }
}

fn warn(path: &Path, error: &str, fallback: &str) {
    println!("cargo::warning={}: {error}; {fallback}", path.display());
}

fn read(path: &Path, fallback: &str) -> Option<String> {
    println!("cargo::rerun-if-changed={}", path.display());
    std::fs::read_to_string(path).map_err(|e| warn(path, &e.to_string(), fallback)).ok()
}

/// A GitHub username: 1–39 ASCII letters, digits and hyphens, not starting or ending with one.
pub fn valid_login(s: &str) -> bool {
    (1..=39).contains(&s.len()) && s.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'-') && !s.starts_with('-') && !s.ends_with('-')
}

/// Whether `s` holds something shaped like an email address: an `@` with a non-blank part before
/// it and a dotted domain after it (`a@b.c`, `<x@y.org>`).
pub fn looks_like_email(s: &str) -> bool {
    s.match_indices('@').any(|(at, _)| {
        let before = s.get(..at).and_then(|b| b.chars().next_back()).is_some_and(|c| !c.is_whitespace() && c != '<');
        let domain: String = s.get(at + 1..).unwrap_or("").chars().take_while(|c| c.is_alphanumeric() || matches!(c, '.' | '-' | '_')).collect();
        let dotted = domain.split('.').filter(|p| !p.is_empty()).count() >= 2;
        before && dotted
    })
}

/// The names of one `[people.<username>]` entry.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct Names {
    pub real_name: Option<String>,
    pub display_name: Option<String>,
    pub sync_github_name: bool,
}

/// What [`parse_people`] read: the entries by username, and the lines it could not use.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct People {
    pub entries: BTreeMap<String, Names>,
    pub problems: Vec<(usize, String)>,
}

/// A one-line string value: `"basic"` with the usual escapes, or `'literal'`; `None` if it is not
/// one. What follows it must be blank or a comment.
fn string_value(v: &str) -> Option<String> {
    let mut chars = v.chars();
    let quote = chars.next().filter(|q| matches!(q, '"' | '\''))?;
    let mut out = String::new();
    loop {
        match chars.next()? {
            c if c == quote => break,
            '\\' if quote == '"' => out.push(match chars.next()? {
                '"' => '"',
                '\\' => '\\',
                'n' => '\n',
                't' => '\t',
                'r' => '\r',
                'b' => '\u{8}',
                'f' => '\u{c}',
                'e' => '\u{1b}',
                u @ ('u' | 'U') => {
                    let digits: String = chars.by_ref().take(if u == 'u' { 4 } else { 8 }).collect();
                    char::from_u32(u32::from_str_radix(&digits, 16).ok()?)?
                }
                _ => return None,
            }),
            c => out.push(c),
        }
    }
    let rest = chars.as_str().trim_start();
    (rest.is_empty() || rest.starts_with('#')).then_some(out)
}

/// Reads `people.toml` leniently: `[people.<username>]` tables with `real_name`, `display_name`
/// (one-line strings) and `sync_github_name` (`true`/`false`). Other keys (`consent_source`) are
/// skipped; a line this reader cannot use is reported and skipped (the strict parser is the
/// xtask's).
pub fn parse_people(text: &str) -> People {
    let mut people = People::default();
    let mut current: Option<String> = None;
    for (i, raw) in text.lines().enumerate() {
        let n = i.saturating_add(1);
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        if let Some(header) = line.strip_prefix('[') {
            let name = header.split(']').next().unwrap_or("").trim();
            current = match name.strip_prefix("people.").map(|l| l.trim().trim_matches('"')) {
                Some(login) if valid_login(login) => {
                    people.entries.entry(login.to_string()).or_default();
                    Some(login.to_string())
                }
                _ => {
                    if name != "people" {
                        people.problems.push((n, format!("`[{name}]` is not a [people.<username>] table")));
                    }
                    None
                }
            };
            continue;
        }
        let Some((key, value)) = line.split_once('=') else {
            people.problems.push((n, "expected `key = value`".into()));
            continue;
        };
        let (key, value) = (key.trim(), value.trim());
        let Some(entry) = current.as_ref().and_then(|l| people.entries.get_mut(l)) else {
            people.problems.push((n, format!("`{key}` is outside a [people.<username>] table")));
            continue;
        };
        match key {
            "real_name" | "display_name" => match string_value(value) {
                Some(s) if key == "real_name" => entry.real_name = Some(s),
                Some(s) => entry.display_name = Some(s),
                None => people.problems.push((n, format!("`{key}` takes a one-line string"))),
            },
            "sync_github_name" => {
                let word = value.split('#').next().unwrap_or("").trim();
                match word {
                    "true" => entry.sync_github_name = true,
                    "false" => entry.sync_github_name = false,
                    _ => people.problems.push((n, "`sync_github_name` takes true or false".into())),
                }
            }
            _ => {}
        }
    }
    people
}

/// A chosen name as a Rust `Option<&str>` literal: trimmed, one line, at most 100 characters;
/// `None` when blank, and when it looks like an email address (its owner is named in `dropped`).
fn name(v: Option<&str>, owner: &str, dropped: &mut Vec<String>) -> String {
    let Some(s) = v.map(|s| s.split(['\n', '\r']).next().unwrap_or("").trim()).filter(|s| !s.is_empty()) else { return "None".into() };
    if looks_like_email(s) {
        dropped.push(format!("a name of @{owner}"));
        return "None".into();
    }
    let s: String = s.chars().filter(|c| !c.is_control()).take(100).collect();
    format!("Some({s:?})")
}

/// A short text field of the JSON (a date, a model's company, name or version) as a Rust string
/// literal: at most 64 characters, empty when missing or when it looks like an email address.
fn text(v: &Value, k: &str, owner: &str, dropped: &mut Vec<String>) -> String {
    let s = v.get(k).and_then(Value::as_str).unwrap_or("");
    if looks_like_email(s) {
        dropped.push(format!("`{k}` of {owner}"));
        return "\"\"".into();
    }
    let s: String = s.chars().filter(|c| !c.is_control()).take(64).collect();
    format!("{s:?}")
}

fn n(v: &Value, k: &str) -> u64 {
    v.get(k).and_then(Value::as_u64).unwrap_or(0)
}

fn rows<'a>(json: &'a Value, k: &str) -> &'a [Value] {
    json.get(k).and_then(Value::as_array).map(Vec::as_slice).unwrap_or(&[])
}

/// The Rust source of the credit tables (`TOTAL_COMMITS`, `CONTRIBUTORS`, `MODELS`) from the JSON
/// and the people.toml entries, and what was left out because it looked like an email address.
pub fn generate(json: &Value, people: &BTreeMap<String, Names>) -> (String, Vec<String>) {
    let mut dropped = Vec::new();
    let mut o = String::new();
    let _ = writeln!(o, "// Generated by crates/ui/build.rs from contributors/contributors.json and contributors/people.toml.");
    let _ = writeln!(o, "pub static TOTAL_COMMITS: u64 = {};", n(json, "commits"));
    let _ = writeln!(o, "pub static CONTRIBUTORS: &[Contributor] = &[");
    for c in rows(json, "contributors") {
        let login = c.get("login").and_then(Value::as_str).unwrap_or("");
        if !valid_login(login) {
            continue;
        }
        // Names only from a verified, self-chosen people.toml entry.
        let verified = c.get("people_entry").and_then(Value::as_bool) == Some(true);
        let entry = people.get(login).filter(|_| verified);
        let display = entry
            .and_then(|e| e.display_name.as_deref())
            .filter(|s| !s.trim().is_empty())
            .or_else(|| entry.filter(|e| e.sync_github_name).and_then(|_| c.get("github_name").and_then(Value::as_str)));
        let real = entry.and_then(|e| e.real_name.as_deref());
        let _ = writeln!(
            o,
            "    Contributor {{ login: {login:?}, display_name: {}, real_name: {}, prs: {}, commits: {}, lines_added: {}, lines_deleted: {}, binary_added: {}, binary_deleted: {}, first_commit: {}, last_commit: {} }},",
            name(display, login, &mut dropped),
            name(real, login, &mut dropped),
            n(c, "prs"),
            n(c, "commits"),
            n(c, "lines_added"),
            n(c, "lines_deleted"),
            n(c, "binary_added"),
            n(c, "binary_deleted"),
            text(c, "first_commit", login, &mut dropped),
            text(c, "last_commit", login, &mut dropped),
        );
    }
    let _ = writeln!(o, "];");
    let _ = writeln!(o, "pub static MODELS: &[Model] = &[");
    for (i, m) in rows(json, "models").iter().enumerate() {
        let owner = format!("model {}", i.saturating_add(1));
        let _ = writeln!(
            o,
            "    Model {{ company: {}, model: {}, version: {}, commits: {}, lines_added: {}, lines_deleted: {} }},",
            text(m, "company", &owner, &mut dropped),
            text(m, "model", &owner, &mut dropped),
            text(m, "version", &owner, &mut dropped),
            n(m, "commits"),
            n(m, "lines_added"),
            n(m, "lines_deleted"),
        );
    }
    let _ = writeln!(o, "];");
    (o, dropped)
}
